CREATE OR REPLACE FUNCTION public.claim_testnet_payout(_id uuid,_operator uuid,_height bigint,_expires timestamptz) RETURNS public.testnet_payouts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.testnet_payouts; BEGIN IF _operator IS NULL OR NOT public.has_role(_operator,'admin') THEN RAISE EXCEPTION 'Admin required'; END IF; IF _id IS NULL OR _height IS NULL OR _expires IS NULL OR _height<0 OR _height>9007199254740991 OR _expires<=now() OR _expires>now()+interval '10 minutes' THEN RAISE EXCEPTION 'Invalid claim window'; END IF; UPDATE public.testnet_payouts SET status='uncertain',claimed_by=_operator,claim_token=gen_random_uuid(),claimed_at=now(),validity_start_height=_height,expires_at=_expires WHERE id=_id AND status='queued' RETURNING * INTO p; IF NOT FOUND THEN RAISE EXCEPTION 'Already claimed; reconcile, never resend'; END IF; RETURN p; END $$;
CREATE OR REPLACE FUNCTION public.complete_testnet_payout(_id uuid,_operator uuid,_token uuid,_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.testnet_payouts; BEGIN IF _operator IS NULL OR NOT public.has_role(_operator,'admin') THEN RAISE EXCEPTION 'Admin required'; END IF; IF _id IS NULL OR _token IS NULL OR _hash IS NULL OR lower(_hash) !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid completion evidence'; END IF; SELECT * INTO p FROM public.testnet_payouts WHERE id=_id FOR UPDATE; IF NOT FOUND OR p.claimed_by IS DISTINCT FROM _operator OR p.claim_token IS DISTINCT FROM _token THEN RAISE EXCEPTION 'Claim mismatch'; END IF; IF p.status='paid' AND p.tx_hash=lower(_hash) THEN RETURN p.id; END IF; IF p.status<>'uncertain' OR (p.tx_hash IS NOT NULL AND p.tx_hash<>lower(_hash)) THEN RAISE EXCEPTION 'Payout mismatch'; END IF; UPDATE public.testnet_payouts SET status='paid',tx_hash=lower(_hash),verified_at=now() WHERE id=p.id; RETURN p.id; END $$;
ALTER TABLE public.testnet_payouts ADD CONSTRAINT testnet_claim_complete CHECK(status='queued' OR (claimed_by IS NOT NULL AND claim_token IS NOT NULL AND claimed_at IS NOT NULL AND validity_start_height IS NOT NULL AND expires_at IS NOT NULL)) NOT VALID;
ALTER TABLE public.testnet_payouts ADD CONSTRAINT testnet_paid_evidence CHECK(status<>'paid' OR (tx_hash IS NOT NULL AND tx_hash ~ '^[a-f0-9]{64}$' AND verified_at IS NOT NULL)) NOT VALID;